      {
        "code": "P272",
        "type": "예방",
        "text": "작업장밖으로오염된의복을반출하지마시오.",
        "line": "p2:L27"
      },
      {
        "code": "P273",
        "type": "예방",
        "text": "환경으로배출하지마시오.",
        "line": "p2:L28"
      },
      {
        "code": "P280",
        "type": "예방",
        "text": "보호장갑보호의보안경안면보호구를착용하십시오",
        "line": "p2:L29"
      },
      {
        "code": "P301+P310",
        "type": "대응",
        "text": "삼켰다면즉시의료기관의사의진찰을받으시오",
        "line": "p2:L31"
      },
      {
        "code": "P330",
        "type": "대응",
        "text": "입을씻어내시오.",
        "line": "p2:L32"
      },
      {
        "code": "P331",
        "type": "대응",
        "text": "토하게하지마시오",
        "line": "p2:L33"
      },
      {
        "code": "P301+P330+P331",
        "type": "대응",
        "text": "삼켰다면입을씻어내시오토하게하려하지마시오",
        "line": "p2:L34"
      },
      {
        "code": "P303+P361+P353",
        "type": "대응",
        "text": "피부또는머리카락에묻으면오염된모든의복을벗으시오피부를물로씻으시오",
        "line": "p2:L35"
      },
      {
        "code": "P304+P340",
        "type": "대응",
        "text": "흡입한경우환자를신선한공기가있는곳으로옮기고호흡하기편하게할것",
        "line": "p2:L36"
      },
      {
        "code": "P305+P351+P338",
        "type": "대응",
        "text": "눈에묻으면몇분간물로조심해서씻으시오가능하면콘택트렌즈를제거하시오계속씻으시오",
        "line": "p2:L37"
      },
      {
        "code": "P310",
        "type": "대응",
        "text": "즉시독성센터의사에연락할것",
        "line": "p2:L38"
      },
      {
        "code": "P333+P313",
        "type": "대응",
        "text": "피부자극성또는홍반이나타나면의학적인조치조언을구하시오",
        "line": "p2:L39"
      },
      {
        "code": "P362+P364",
        "type": "대응",
        "text": "오염된의복은벗고다시사용전세척하시오.",
        "line": "p2:L40"
      },
      {
        "code": "P370+P378",
        "type": "대응",
        "text": "화재시불을끄기위해적절한소화제를사용하시오.",
        "line": "p2:L41"
      },
      {
        "code": "P391",
        "type": "대응",
        "text": "누출물을모으시오.",
        "line": "p2:L42"
      },
      {
        "code": "P403+P233",
        "type": "저장",
        "text": "용기는환기가잘되는곳에단단히밀폐하여저장하시오.",
        "line": "p2:L44"
      },
      {
        "code": "P403+P235",
        "type": "저장",
        "text": "환기가잘되는곳에보관하고저온으로유지하시오",
        "line": "p2:L45"
      },
      {
        "code": "P405",
        "type": "저장",
        "text": "잠금장치가있는저장장소에저장하시오.",
        "line": "p2:L46"
      },
      {
        "code": "P501",
        "type": "폐기",
        "text": "폐기물관리법에명시된내용에따라내용물과용기를폐기처분하십시오.",
        "line": "p2:L48"
      }
    ],
